  "bots.setup.callbackUrlTitle": "URL обратного вызова",
  "bots.setup.callbackUrlDescription.webhook": "Ваша внешняя система должна отправлять обратные вызовы о входящих сообщениях на этот адрес. Асинхронные исходящие ответы по-прежнему используют URL вебхука, указанный слева.",
  "bots.setup.callbackUrlDescription.webhookBind": "Привязка вебхука использует тот же адрес: отправьте сюда приватный запрос обратного вызова с текстом = /bind <code>.",
  "bots.setup.guide.telegram.create.1": "Откройте @BotFather в Telegram и создайте нового бота.",
  "bots.setup.guide.telegram.create.2": "Скопируйте HTTP API токен, выданный BotFather, и вставьте его в эту форму.",
  "bots.setup.guide.telegram.create.3": "Лучше сразу открыть личный чат с ботом — именно туда нужно отправить команду привязки.",
  "bots.setup.guide.telegram.bind.1": "Вернитесь в Telegram и откройте личный чат с созданным ботом.",
  "bots.setup.guide.telegram.bind.2": "Если чат ещё не был начат, нажмите Start или сначала отправьте любое сообщение, затем отправьте {command}.",
  "bots.setup.guide.telegram.bind.3": "Вернитесь сюда после подтверждения привязки в Telegram.",
  "bots.setup.guide.weixin.create.1": "Запустите вход по QR-коду Weixin, отсканируйте код в Weixin и подтвердите на телефоне.",
  "bots.setup.guide.weixin.create.2": "ZCode автоматически сохранит bot_token, выданный iLink; после сканирования отправьте боту любое сообщение в Weixin, чтобы активировать чат.",
  "bots.setup.guide.weixin.create.3": "ZCode использует встроенный клиент iLink: `/ilink/bot/getupdates` для длинного опроса и `/ilink/bot/sendmessage` для ответов.",
  "bots.setup.guide.weixin.bind.1": "Откройте диалог Weixin, который нужно привязать.",
  "bots.setup.guide.weixin.bind.2": "Отправьте {command}.",
  "bots.setup.guide.weixin.bind.3": "После успешной привязки вернитесь сюда, чтобы завершить настройку рабочего пространства и параметров CLI по умолчанию.",
  "bots.setup.guide.feishu.create.1": "Создайте собственное приложение в консоли разработчика Feishu/Lark и включите возможность бота.",
  "bots.setup.guide.feishu.create.2": "Скопируйте App ID и App Secret, затем включите события постоянного соединения для `im.message.receive_v1` и действий с карточками.",
  "bots.setup.guide.feishu.create.3": "Выберите здесь соответствующий домен Feishu или Lark, затем вставьте учётные данные в форму.",
  "bots.setup.guide.feishu.bind.1": "Установите приложение в ваш тенант и откройте диалог с ботом.",
  "bots.setup.guide.feishu.bind.2": "Отправьте {command} в этом диалоге.",
  "bots.setup.guide.feishu.bind.3": "После успешной привязки вернитесь сюда, чтобы завершить настройку рабочего пространства и параметров CLI по умолчанию.",
  "bots.setup.guide.webhook.create.1": "Режим вебхука не требует собственного бота в стороннем продукте; вашей интеграции достаточно отправлять сообщения в ZCode методом POST.",
  "bots.setup.guide.webhook.create.2": "Сначала задайте общий секрет; если хотите получать асинхронные ответы, также добавьте исходящий URL вебхука.",
  "bots.setup.guide.webhook.create.3": "Используйте один стабильный userId для каждого внешнего пользователя, чтобы привязка и будущий контекст указывали на одного и того же человека.",
  "bots.setup.guide.webhook.bind.1": "Отправьте обратный вызов приватного сообщения методом POST на эндпоинт `/api/bots/webhook` ZCode.",
  "bots.setup.guide.webhook.bind.2": "Полезная нагрузка должна как минимум содержать этот botId, стабильный userId, `chatType: \"private\"` и text, равный {command}.",
  "bots.setup.guide.webhook.bind.3": "Если бот использует секрет, также передайте `x-zcode-bot-secret`; затем вернитесь сюда после успешной привязки.",
