  "settings.httpProxy": "HTTP-прокси",
  "settings.httpProxyDescription": "Направляет исходящий трафик модели, MCP, командных инструментов и рендерера приложения через этот прокси; системные переменные окружения не читаются. Если оставить поле пустым, этот трафик будет подключаться напрямую, а встроенный браузер будет следовать системным настройкам прокси. Перезапустите приложение, чтобы изменения вступили в силу.",
