  "settings.modelProvider.help.inputModalities": "Укажите типы содержимого, которые может принимать модель:\n\n- **Текст**: принимает текстовое содержимое. Обязательно.\n- **Изображения**: принимает изображения.\n- **Видео**: принимает видео.\n- **PDF**: принимает PDF-документы напрямую.",
  "settings.modelProvider.help.outputModalities": "Тип содержимого ответов модели. Сейчас поддерживается только текст.",
  "settings.modelProvider.help.capabilities": "- **Структурированный вывод**: поддерживает ограничения JSON Schema на поля, типы и структуру вывода.\n- **Встроенный веб-поиск**: поддерживает встроенный веб-поиск API модели.\n- **Системные сообщения во время диалога**: поддерживает вставку системных инструкций во время диалога.\n\nНе включайте возможности, которые модель не поддерживает.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Настройте доступные в чате уровни рассуждений. **Они должны быть упорядочены от самого низкого к самому высокому усилию рассуждения**.\nНе настраивайте уровни рассуждений, которые модель не поддерживает.",
  "settings.modelProvider.help.reasoningLevelMapping": "Используйте CEL-выражение, чтобы сопоставить текущий уровень рассуждений, `reasoningLevel`, с полями запроса к API модели. JSON-объект, возвращаемый выражением, объединяется с телом исходящего запроса.",
  "settings.modelProvider.help.advanced": "**Схема инструментов MFJS**: включает совместимость с Moonshot Flavored JSON Schema, которая обычно используется API модели Kimi от Moonshot. Включайте только тогда, когда API модели требует этот формат.",
  "settings.modelProvider.help.followRecommendedConfig": "Подбирает рекомендуемую конфигурацию по ID модели, Base URL и формату API. ZCode постоянно обновляет рекомендации и автоматически синхронизирует их с вами.\nКогда вы вручную меняете настройку, она переходит под ручное управление и перестаёт следовать обновлениям рекомендаций; остальные настройки остаются под управлением умной конфигурации.",
  "settings.modelProvider.modelDefaultsLoaded": "Умная конфигурация подобрана для этой модели",
